discrete ClockSignalGenerator
port:
    event input real StartSignal;
    event input real StopSignal;
    event output real ClockOutput;
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(StartSignal) then
            transition(RunningState);
        end;
    end;

    state RunningState
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(InitialState);
            out
                send(ClockOutput, 1);
        end;
        when receive(StopSignal) then
            transition(InitialState);
        end;
    end;
end;
end;

discrete ClockSignalSynchronizer
port:
    event input real ClockInput;
    event input real ErrorDetected;
    event input real ResetSignal;
    event output real SynchronizationStatus;
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(ClockInput) then
            transition(SynchronizationProcessingState);
        end;
    end;

    state SynchronizationProcessingState
        when entry() then
            statehold(0);
        end;
        when not receive(ClockInput) then
            transition(InitialState);
        end;
        when receive(ErrorDetected) then
            transition(ErrorHandlingState);
        end;
    end;

    state ErrorHandlingState
        when entry() then
            statehold(0);
        end;
        when receive(ResetSignal) then
            transition(InitialState);
        end;
        when timeover() then
            transition(SynchronizationProcessingState);
        out
            send(SynchronizationStatus, 1);
        end;
    end;
end;
end;

discrete ClockSignalMonitorAndCalibrator
port:
    event input real StartMonitoringSignal;
    event input real StopMonitoringSignal;
    event input real QualityIssueDetected;
    event input real ResetSignal;
    event output real CalibrationStatus;
    event output real AlarmStatus;
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(StartMonitoringSignal) then
            transition(MonitoringState);
        end;
    end;

    state MonitoringState
        when entry() then
            statehold(0);
        end;
        when receive(QualityIssueDetected) then
            transition(CalibrationState);
        end;
        when receive(StopMonitoringSignal) then
            transition(InitialState);
        end;
    end;

    state CalibrationState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(MonitoringState);
        out
            send(CalibrationStatus, 1);
        end;
        when receive(QualityIssueDetected) then
            transition(AlarmState);
        end;
    end;

    state AlarmState
        when entry() then
            statehold(0);
        end;
        when receive(ResetSignal) then
            transition(InitialState);
        end;
    end;
end;
end;

couple ClockGeneratorSystem
import architectureModels.ClockSignalGenerator as ClockGen;
import architectureModels.ClockSignalSynchronizer as ClockSync;
import architectureModels.ClockSignalMonitorAndCalibrator as ClockMonCal;
part:
    ClockGen ClockGenInstance;
    ClockSync ClockSyncInstance;
    ClockMonCal ClockMonCalInstance;
connection:
    connect(ClockGenInstance.ClockOutput, ClockSyncInstance.ClockInput);
    connect(ClockSyncInstance.SynchronizationStatus, ClockMonCalInstance.QualityIssueDetected);
    connect(ClockMonCalInstance.CalibrationStatus, ClockSyncInstance.ResetSignal);
end;
